import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_PHONE_MARKER_RE = re.compile(r"ext|x|#")
_ZIP_PLUS4_RE = re.compile(r"([0-9]{4,5})-[0-9]{4}")
_FOUR_DIGIT_RE = re.compile(r"[0-9]{4}")
_FIVE_DIGIT_RE = re.compile(r"[0-9]{5}")
_TAG_SPLIT_RE = re.compile(r"[;,]")
_OPTED_OUT_VALUES = {"y", "yes", "true", "1"}


def _normalize_email(raw):
    """Return the normalized email, or "" if it is not valid."""
    s = raw.strip()
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.replace(".", "")
        local = local.split("+", 1)[0]
        domain = "gmail.com"
    if not local:
        return ""
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return ""
    return f"{local}@{domain}"


def _normalize_phone(raw):
    """Return the normalized 10-digit phone, or "" if it is not valid."""
    s = raw.lower()
    m = _PHONE_MARKER_RE.search(s)
    if m:
        s = s[:m.start()]
    digits = "".join(c for c in s if "0" <= c <= "9")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    """Return the normalized 5-digit ZIP, or "" if it is not valid."""
    z = raw.strip()
    m = _ZIP_PLUS4_RE.fullmatch(z)
    if m:
        z = m.group(1)
    if _FOUR_DIGIT_RE.fullmatch(z):
        z = "0" + z
    return z if _FIVE_DIGIT_RE.fullmatch(z) else ""


def _normalize_name(raw):
    """Strip, and title-case the name only if it is entirely upper or lower case."""
    n = raw.strip()
    if n and (n.isupper() or n.islower()):
        n = n.title()
    return n


def _parse_updated(raw):
    """Parse an 'updated' value into a datetime. Raises ValueError if unrecognized."""
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def dedupe_contacts(rows):
    # Pass 1: normalize each row and drop rows with no valid email or phone.
    records = []
    for pos, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        if not email and not phone:
            continue
        last = _normalize_name(row.get("last_name", ""))
        source = row.get("source", "").strip().lower()
        records.append({
            "pos": pos,
            "email": email,
            "phone": phone,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": last,
            "last_key": last.casefold(),
            "zip": _normalize_zip(row.get("zip", "")),
            "source": source,
            "manual": source == "manual",
            "tags": {t.strip().lower() for t in _TAG_SPLIT_RE.split(row.get("tags", ""))} - {""},
            "opted_out": row.get("opted_out", "").strip().lower() in _OPTED_OUT_VALUES,
            "updated": _parse_updated(row.get("updated", "")),
        })

    # Pass 2: link matching rows with union-find (handles transitivity).
    n = len(records)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone_last = {}
    for idx, rec in enumerate(records):
        if rec["email"]:
            if rec["email"] in first_by_email:
                union(first_by_email[rec["email"]], idx)
            else:
                first_by_email[rec["email"]] = idx
        if rec["phone"] and rec["last_key"]:
            key = (rec["phone"], rec["last_key"])
            if key in first_by_phone_last:
                union(first_by_phone_last[key], idx)
            else:
                first_by_phone_last[key] = idx

    # Group record indices by root. Dict insertion order follows each
    # group's earliest row, because records are visited in input order.
    groups = {}
    for idx in range(n):
        groups.setdefault(find(idx), []).append(idx)

    def pick(members, field):
        """Choose the best non-empty value of `field` among group members."""
        cands = [records[i] for i in members if records[i][field]]
        if not cands:
            return ""
        # Stable sorts applied from least to most significant key:
        # earliest input position, then most recent updated, then manual first.
        cands = sorted(cands, key=lambda r: r["pos"])
        cands = sorted(cands, key=lambda r: r["updated"], reverse=True)
        cands = sorted(cands, key=lambda r: not r["manual"])
        return cands[0][field]

    result = []
    for members in groups.values():
        all_tags = set()
        for i in members:
            all_tags |= records[i]["tags"]
        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(records[i]["opted_out"] for i in members) else "N",
            "updated": max(records[i]["updated"] for i in members).strftime("%Y-%m-%d"),
        })
    return result
